create or replace function public.school_admin_update_other_member(p_id uuid,p_full_name text,p_password text default null,p_role_title text default null,p_department text default null,p_phone text default null,p_email text default null,p_details text default null)
returns jsonb language plpgsql security definer set search_path='' as $$ declare v_login text; v_hash text; begin if not public.store_is_admin() then raise exception 'Not authorized'; end if; if nullif(trim(p_full_name),'') is null then raise exception 'Name is required'; end if; v_hash:=case when nullif(p_password,'') is null then null else crypt(p_password,gen_salt('bf')) end; update public.school_other_members set full_name=trim(p_full_name),role_title=nullif(trim(p_role_title),''),department=nullif(trim(p_department),''),phone=nullif(trim(p_phone),''),email=nullif(trim(p_email),''),details=nullif(trim(p_details),''),login_password=coalesce(nullif(p_password,''),login_password),password_hash=coalesce(v_hash,password_hash),updated_at=now() where id=p_id returning other_id into v_login; if v_login is null then raise exception 'Member not found'; end if; if v_hash is not null then update public.store_users set password_hash=v_hash,is_active=true,updated_at=now() where lower(login_id)=lower(v_login); end if; return jsonb_build_object('member_id',v_login); end; $$;
grant execute on function public.school_admin_update_other_member(uuid,text,text,text,text,text,text,text) to authenticated;

create or replace function public.school_admin_deactivate_other_member(p_id uuid)
returns void language plpgsql security definer set search_path='' as $$ declare v_login text; begin if not public.store_is_admin() then raise exception 'Not authorized'; end if; update public.school_other_members set is_active=false,updated_at=now() where id=p_id returning other_id into v_login; if v_login is null then raise exception 'Member not found'; end if; update public.store_users set is_active=false where lower(login_id)=lower(v_login); end; $$;
grant execute on function public.school_admin_deactivate_other_member(uuid) to authenticated;
